macro_rules! deps {
    () => {
        Exclusive!();
        Shared!();
    };
}

macro_rules! Validity {
    () => {
        deps!();
        # [doc = " The validity invariant of a [`Ptr`][super::Ptr]."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " In this section, we will use `Ptr<T, V>` as a shorthand for `Ptr<T, I:"] # [doc = " Invariants<Validity = V>>` for brevity."] # [doc = ""] # [doc = " Each `V: Validity` defines a set of bit values which may appear in the"] # [doc = " referent of a `Ptr<T, V>`, denoted `S(T, V)`. Each `V: Validity`, in its"] # [doc = " documentation, provides a definition of `S(T, V)` which must be valid for"] # [doc = " all `T: ?Sized`. Any `V: Validity` must guarantee that this set is only a"] # [doc = " function of the *bit validity* of the referent type, `T`, and not of any"] # [doc = " other property of `T`. As a consequence, given `V: Validity`, `T`, and `U`"] # [doc = " where `T` and `U` have the same bit validity, `S(V, T) = S(V, U)`."] # [doc = ""] # [doc = " It is guaranteed that the referent of any `ptr: Ptr<T, V>` is a member of"] # [doc = " `S(T, V)`. Unsafe code must ensure that this guarantee will be upheld for"] # [doc = " any existing `Ptr`s or any `Ptr`s that that code creates."] # [doc = ""] # [doc = " An important implication of this guarantee is that it restricts what"] # [doc = " transmutes are sound, where \"transmute\" is used in this context to refer to"] # [doc = " changing the referent type or validity invariant of a `Ptr`, as either"] # [doc = " change may change the set of bit values permitted to appear in the referent."] # [doc = " In particular, the following are necessary (but not sufficient) conditions"] # [doc = " in order for a transmute from `src: Ptr<T, V>` to `dst: Ptr<U, W>` to be"] # [doc = " sound:"] # [doc = " - If `S(T, V) = S(U, W)`, then no restrictions apply; otherwise,"] # [doc = " - If `dst` permits mutation of its referent (e.g. via `Exclusive` aliasing"] # [doc = "   or interior mutation under `Shared` aliasing), then it must hold that"] # [doc = "   `S(T, V) ⊇ S(U, W)` - in other words, the transmute must not expand the"] # [doc = "   set of allowed referent bit patterns. A violation of this requirement"] # [doc = "   would permit using `dst` to write `x` where `x ∈ S(U, W)` but `x ∉ S(T,"] # [doc = "   V)`, which would violate the guarantee that `src`'s referent may only"] # [doc = "   contain values in `S(T, V)`."] # [doc = " - If the referent may be mutated without going through `dst` while `dst` is"] # [doc = "   live (e.g. via interior mutation on a `Shared`-aliased `Ptr` or `&`"] # [doc = "   reference), then it must hold that `S(T, V) ⊆ S(U, W)` - in other words,"] # [doc = "   the transmute must not shrink the set of allowed referent bit patterns. A"] # [doc = "   violation of this requirement would permit using `src` or another"] # [doc = "   mechanism (e.g. a `&` reference used to derive `src`) to write `x` where"] # [doc = "   `x ∈ S(T, V)` but `x ∉ S(U, W)`, which would violate the guarantee that"] # [doc = "   `dst`'s referent may only contain values in `S(U, W)`."] pub unsafe trait Validity : Sealed { }
    };
}

Validity!()